import { Profile } from './types';
import { parseProfile } from './parser';

export class ProfileService {
  constructor(readonly profile: Profile) {}

  patch(input: unknown): Profile {
    // Validation happens entirely inside parseProfile, so an invalid input throws
    // before any stored field is touched and storage stays unchanged.
    const patch = parseProfile(input);
    if (patch.displayName.kind === 'set') this.profile.displayName = patch.displayName.value;
    if (patch.tags.kind === 'set') this.profile.tags = patch.tags.value;
    // parser never returns the caller's tags array, storage only ever gets fresh arrays.
    return this.profile;
  }
}
